1	/**
2	 * Angular CLI workspace and TypeScript configuration migration.
3	 *
4	 * The shapes handled here are the ones the Angular CLI itself defines and the
5	 * ones the modern `@angular-devkit/build-angular` schema no longer accepts. No
6	 * capability branches on a project name, an application name or a source
7	 * string: every project in `angular.json` is walked, whatever it is called.
8	 *
9	 * Both entry points parse strict JSON. A configuration carrying comments
10	 * (JSONC, which the CLI also accepts) is refused with a diagnosable error
11	 * rather than silently reserialized, because rewriting it would delete the
12	 * comments without saying so.
13	 */
14	
15	import { REMOVED_BUILDER_PACKAGES, compareStrings } from './angular-target-cell.ts';
16	import type { AngularTargetCell } from './angular-target-cell.ts';
17	
18	export type ConfigChange = Readonly<{ path: string; from: string | null; to: string | null }>;
19	
20	export type WorkspaceMigration = Readonly<{
21		config: string;
22		changes: readonly ConfigChange[];
23		removedPackages: readonly string[];
24		unhandled: readonly string[];
25	}>;
26	
27	type JsonObject = Record<string, unknown>;
28	
29	/**
30	 * Builder options the modern devkit schema no longer accepts. A build fails
31	 * outright on an unknown option, so leaving one in place is not a cosmetic
32	 * defect.
33	 *
34	 * `extractCss` was removed once CSS extraction became unconditional in
35	 * production; `es5BrowserSupport` and `showCircularDependencies` went with the
36	 * differential-loading and webpack-plugin surfaces they configured;
37	 * `experimentalRollupPass` and `lazyModules` were experimental options the
38	 * devkit dropped.
39	 */
40	export const REMOVED_BUILDER_OPTIONS: readonly string[] = Object.freeze([
41		'es5BrowserSupport',
42		'experimentalRollupPass',
43		'extractCss',
44		'lazyModules',
45		'showCircularDependencies',
46	]);
47	
48	/**
49	 * Builders the modern devkit no longer ships at all. The target that uses one
50	 * cannot be carried across the hop: it is removed, and the packages it existed
51	 * to run are reported so the manifest alignment can drop them too. Replacing
52	 * the capability the target provided (a linter, an end-to-end runner) is a
53	 * decision about the project, not a mechanical rewrite, so this capability
54	 * makes no attempt at one and says so.
55	 */
56	export const REMOVED_BUILDERS: readonly string[] = Object.freeze(
57		Object.keys(REMOVED_BUILDER_PACKAGES).sort(compareStrings),
58	);
59	
60	/** Builders this capability recognises as still present on a modern line. */
61	export const CARRIED_BUILDERS: readonly string[] = Object.freeze([
62		'@angular-devkit/build-angular:browser',
63		'@angular-devkit/build-angular:dev-server',
64		'@angular-devkit/build-angular:extract-i18n',
65		'@angular-devkit/build-angular:karma',
66		'@angular-devkit/build-angular:ng-packagr',
67		'@angular-devkit/build-angular:server',
68	]);
69	
70	/**
71	 * True when the document carries a `//` or `/* … *\/` comment outside a string
72	 * literal. String contents are skipped, because a JSON string legitimately
73	 * holds both sequences — a glob such as `**\/node_modules/**` and a URL both
74	 * do — and treating those as comments would refuse a strict JSON document.
75	 */
76	export function carriesJsonComment(source: string): boolean {
77		let inString = false;
78		for (let index = 0; index < source.length; index += 1) {
79			const character = source[index];
80			if (inString) {
81				if (character === '\\') index += 1;
82				else if (character === '"') inString = false;
83				continue;
84			}
85			if (character === '"') {
86				inString = true;
87				continue;
88			}
89			if (character !== '/') continue;
90			const next = source[index + 1];
91			if (next === '/' || next === '*') return true;
92		}
93		return false;
94	}
95	
96	function parseStrictJson(source: string, kind: string): JsonObject {
97		if (carriesJsonComment(source))
98			throw new Error(
99				`Angular ${kind} migration: the configuration appears to carry comments. ` +
100					'This capability rewrites strict JSON only; a JSONC configuration would lose ' +
101					'its comments silently, so it is refused instead.',
102			);
103		const parsed: unknown = JSON.parse(source);
104		if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))
105			throw new Error(`Angular ${kind} migration: the configuration is not a JSON object`);
106		return parsed as JsonObject;
107	}
108	
109	function serialize(value: unknown): string {
110		return `${JSON.stringify(value, null, 2)}\n`;
111	}
112	
113	function objectAt(value: unknown): JsonObject | null {
114		return typeof value === 'object' && value !== null && !Array.isArray(value)
115			? (value as JsonObject)
116			: null;
117	}
118	
119	function migrateBuilderOptions(
120		options: JsonObject,
121		prefix: string,
122		changes: ConfigChange[],
123	): JsonObject {
124		const next: JsonObject = {};
125		for (const [key, value] of Object.entries(options)) {
126			if (REMOVED_BUILDER_OPTIONS.includes(key)) {
127				changes.push({ path: `${prefix}.${key}`, from: JSON.stringify(value), to: null });
128				continue;
129			}
130			if (key === 'polyfills' && typeof value === 'string') {
131				next[key] = [value];
132				changes.push({
133					path: `${prefix}.polyfills`,
134					from: JSON.stringify(value),
135					to: JSON.stringify([value]),
136				});
137				continue;
138			}
139			next[key] = value;
140		}
141		return next;
142	}
143	
144	/**
145	 * Migrate an `angular.json` workspace onto the declared cell.
146	 *
147	 * Three mechanical changes, each one a shape the modern schema rejects: the
148	 * workspace-level `defaultProject` key, builder options the devkit removed
149	 * (in a target's `options` and in every named configuration), and the
150	 * `polyfills` option's string form, which became an array of entry points.
151	 * Targets whose builder no longer exists are removed and reported.
152	 */
153	export function migrateAngularWorkspace(
154		source: string,
155		cell: AngularTargetCell,
156	): WorkspaceMigration {
157		const workspace = parseStrictJson(source, 'workspace');
158		const changes: ConfigChange[] = [];
159		const removedPackages = new Set<string>();
160		const unhandled: string[] = [];
161		const next: JsonObject = {};
162		for (const [key, value] of Object.entries(workspace)) {
163			if (key === 'defaultProject') {
164				changes.push({ path: 'defaultProject', from: JSON.stringify(value), to: null });
165				continue;
166			}
167			next[key] = value;
168		}
169		const projects = objectAt(next['projects']);
170		if (projects !== null) {
171			const migratedProjects: JsonObject = {};
172			for (const [projectName, projectValue] of Object.entries(projects)) {
173				const project = objectAt(projectValue);
174				if (project === null) {
175					migratedProjects[projectName] = projectValue;
176					continue;
177				}
178				const architect = objectAt(project['architect']) ?? objectAt(project['targets']);
179				if (architect === null) {
180					migratedProjects[projectName] = project;
181					continue;
182				}
183				const architectKey = objectAt(project['architect']) === null ? 'targets' : 'architect';
184				const migratedTargets: JsonObject = {};
185				for (const [targetName, targetValue] of Object.entries(architect)) {
186					const target = objectAt(targetValue);
187					const builder = target === null ? null : target['builder'];
188					const targetPath = `projects.${projectName}.${architectKey}.${targetName}`;
189					if (typeof builder === 'string' && REMOVED_BUILDERS.includes(builder)) {
190						changes.push({ path: targetPath, from: builder, to: null });
191						for (const name of REMOVED_BUILDER_PACKAGES[builder] ?? [])
192							removedPackages.add(name);
193						unhandled.push(
194							`${targetPath} used ${builder}, which the ${cell.angularLine} devkit does not ship; ` +
195								'the target was removed and no replacement capability was chosen for it',
196						);
197						continue;
198					}
199					if (typeof builder === 'string' && !CARRIED_BUILDERS.includes(builder)) {
200						unhandled.push(
201							`${targetPath} uses ${builder}, which this capability does not recognise; ` +
202								'its options were left untouched',
203						);
204						migratedTargets[targetName] = targetValue;
205						continue;
206					}
207					if (target === null) {
208						migratedTargets[targetName] = targetValue;
209						continue;
210					}
211					const migratedTarget: JsonObject = { ...target };
212					const options = objectAt(target['options']);
213					if (options !== null)
214						migratedTarget['options'] = migrateBuilderOptions(
215							options,
216							`${targetPath}.options`,
217							changes,
218						);
219					const configurations = objectAt(target['configurations']);
220					if (configurations !== null) {
221						const migratedConfigurations: JsonObject = {};
222						for (const [name, value] of Object.entries(configurations)) {
223							const configuration = objectAt(value);
224							migratedConfigurations[name] =
225								configuration === null
226									? value
227									: migrateBuilderOptions(
228											configuration,
229											`${targetPath}.configurations.${name}`,
230											changes,
231										);
232						}
233						migratedTarget['configurations'] = migratedConfigurations;
234					}
235					migratedTargets[targetName] = migratedTarget;
236				}
237				migratedProjects[projectName] = { ...project, [architectKey]: migratedTargets };
238			}
239			next['projects'] = migratedProjects;
240		}
241		return Object.freeze({
242			config: serialize(next),
243			changes: Object.freeze(changes),
244			removedPackages: Object.freeze([...removedPackages].sort(compareStrings)),
245			unhandled: Object.freeze(unhandled),
246		});
247	}
248	
249	export type TsConfigMigration = Readonly<{
250		config: string;
251		changes: readonly ConfigChange[];
252		unhandled: readonly string[];
253	}>;
254	
255	/**
256	 * Migrate a workspace `tsconfig.json` onto the declared cell.
257	 *
258	 * The Angular compiler on a modern line emits ES2022 output and requires
259	 * `useDefineForClassFields: false` at that target, because TypeScript's
260	 * standards-compliant class-field semantics would otherwise overwrite the
261	 * fields Angular's decorators initialise. `enableIvy` is removed: Ivy is the
262	 * only compiler left, and the option is no longer read.
263	 */
264	export function migrateAngularTsConfig(source: string, cell: AngularTargetCell): TsConfigMigration {
265		const config = parseStrictJson(source, 'tsconfig');
266		const changes: ConfigChange[] = [];
267		const unhandled: string[] = [];
268		const next: JsonObject = { ...config };
269		const compilerOptions = objectAt(config['compilerOptions']);
270		if (compilerOptions === null) {
271			unhandled.push('the tsconfig declares no compilerOptions; nothing was aligned');
272			return Object.freeze({
273				config: serialize(next),
274				changes: Object.freeze(changes),
275				unhandled: Object.freeze(unhandled),
276			});
277		}
278		const migrated: JsonObject = { ...compilerOptions };
279		for (const key of ['target', 'module'] as const) {
280			const from = compilerOptions[key];
281			if (from === 'ES2022') continue;
282			migrated[key] = 'ES2022';
283			changes.push({
284				path: `compilerOptions.${key}`,
285				from: from === undefined ? null : JSON.stringify(from),
286				to: '"ES2022"',
287			});
288		}
289		if (compilerOptions['useDefineForClassFields'] !== false) {
290			migrated['useDefineForClassFields'] = false;
291			changes.push({
292				path: 'compilerOptions.useDefineForClassFields',
293				from:
294					compilerOptions['useDefineForClassFields'] === undefined
295						? null
296						: JSON.stringify(compilerOptions['useDefineForClassFields']),
297				to: 'false',
298			});
299		}
300		next['compilerOptions'] = migrated;
301		const angularCompilerOptions = objectAt(config['angularCompilerOptions']);
302		if (angularCompilerOptions !== null && 'enableIvy' in angularCompilerOptions) {
303			const { enableIvy, ...rest } = angularCompilerOptions;
304			next['angularCompilerOptions'] = rest;
305			changes.push({
306				path: 'angularCompilerOptions.enableIvy',
307				from: JSON.stringify(enableIvy),
308				to: null,
309			});
310		}
311		unhandled.push(
312			`compilerOptions.lib was left as declared; the ${cell.angularLine} line does not require a specific lib set ` +
313				'and narrowing one could remove a type surface the application relies on',
314		);
315		return Object.freeze({
316			config: serialize(next),
317			changes: Object.freeze(changes),
318			unhandled: Object.freeze(unhandled),
319		});
320	}
