33	const evidenceDirectory = path.join(repositoryRoot, 'evidence/runs/angular-factoriolab');
34	
35	/** The single current source-migration record. See {@link SUPERSEDES}. */
36	export const MIGRATION_RECORD_FILE = 'm2-source-migration.json';
37	
