142		migration: AngularMigration,
143		unit: string,
144		consentId: string,
145	): MigrationRecord {
146		const body = {
147			schemaVersion: 'versionless.angular-factoriolab-source-migration.v1',
148			unit,
149			consentId,
150			result: 'source-migration-recorded',
151			supersedes: SUPERSEDES,
152			source: {
153				commit: FACTORIOLAB_COMMIT,
154				archiveUrl: FACTORIOLAB_ARCHIVE_URL,
155				archiveSha256: FACTORIOLAB_ARCHIVE_SHA256,
156				bytes: FACTORIOLAB_ARCHIVE_BYTES,
157			},
158			cell: {
159				id: ANGULAR_16_BROWSER_CELL.id,
160				angularLine: ANGULAR_16_BROWSER_CELL.angularLine,
161				builder: ANGULAR_16_BROWSER_CELL.builder,
162				nodeLine: ANGULAR_16_BROWSER_CELL.nodeLine,
163				typescriptRange: ANGULAR_16_BROWSER_CELL.typescriptRange,
164				rationale: ANGULAR_16_BROWSER_CELL.rationale,
