171					.filter((entry) => entry.changed)
172					.map((entry) => ({
173						path: entry.path,
174						kind: entry.kind,
175						sha256Before: entry.sha256Before,
176						sha256After: entry.sha256After,
177						changes: entry.changes,
178					})),
179			},
180			unhandled: migration.unhandled,
181			notEstablished: NOT_ESTABLISHED,
182			nonclaims: NONCLAIMS,
183		} as const;
184		return Object.freeze({ ...body, digest: sha256(canonical(body)) });
185	}
