187	/** Recompute the record's digest; a record that does not seal is rejected. */
188	export function verifyMigrationRecord(record: MigrationRecord): MigrationRecord {
189		const { digest, ...body } = record;
190		const recomputed = sha256(canonical(body));
191		if (recomputed !== digest)
